'use strict';
/**
 * Builds docs/www-us-banner/www-us-banner-entry.html (the script-manager box CONTENT for www.momuto.com) from the two sources,
 * same pattern as build-account-brand-entry.js. `--check` exits 1 when the generated file is stale or a guard fails.
 * Guards: no "</style" / "</script" inside the content, balanced CSS braces, the JS parses, a version in the CSS, the www host gate in the JS.
 */
const fs = require('fs'), path = require('path'), vm = require('vm');
const DIR = path.join(__dirname, '..', 'docs', 'www-us-banner');
const css = fs.readFileSync(path.join(DIR, 'www-us-banner.css'), 'utf8');
const js = fs.readFileSync(path.join(DIR, 'www-us-banner.js'), 'utf8');
const minCss = c => c.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\s+/g, ' ').replace(/\s*([{};,])\s*/g, '$1').replace(/:\s+/g, ':').replace(/;}/g, '}').trim();
const minJs = j => j.replace(/^\s*\/\*[\s\S]*?\*\/\s*/, '').split('\n').filter(l => !/^\s*\/\//.test(l)).join('\n').trim();
const problems = [];
const version = (css.match(/--mo-www-entry:\s*(v\d+)/) || [])[1];
if (!version) problems.push('CSS must declare :root { --mo-www-entry: vN }');
if (!new RegExp(`VERSION = '${version}'`).test(js)) problems.push('JS VERSION must equal the CSS version');
if (/<\/(style|script)/i.test(css) || /<\/(style|script)/i.test(js)) problems.push('"</style" or "</script" inside the content');
if ((css.match(/{/g) || []).length !== (css.match(/}/g) || []).length) problems.push('CSS braces do not balance');
if (!/location\.hostname !== 'www\.momuto\.com'/.test(js)) problems.push('JS lost the www host gate for the banner');
try { new vm.Script(js); } catch (e) { problems.push('JS does not parse: ' + e.message); }
if (problems.length) { console.error('✖ ' + problems.join('\n✖ ')); process.exit(1); }
const out = `<!-- MOMUTO www entry ${version} — script-manager entry for www.momuto.com ONLY, box CONTENT (the platform adds its own markers).
     GENERATED by scripts/build-www-us-banner-entry.js from docs/www-us-banner/www-us-banner.css + .js — do not edit here.
     1) demotes the theme-printed CMS title from <h1 class="title"> to <div class="title"> on pages and posts (one h1 per page);
     2) shows a dismissible "Shopping from the US?" bar linking to us.momuto.com for en-US browsers in a US time zone (link, never redirect).
     To undo: disable or delete this entry. Docs: docs/www-us-banner/README.md -->
<style>${minCss(css)}</style>
<script>${minJs(js)}</script>
`;
const target = path.join(DIR, 'www-us-banner-entry.html');
if (process.argv.includes('--check')) {
  const cur = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
  if (cur !== out) { console.error('✖ www-us-banner-entry.html is stale — run node scripts/build-www-us-banner-entry.js'); process.exit(1); }
  console.log('✓ www-us-banner entry up to date (' + version + ')'); process.exit(0);
}
fs.writeFileSync(target, out);
console.log(`✓ wrote ${path.relative(process.cwd(), target)} (${version}, ${out.length} bytes)`);
